svg.script:

function openBase64Tab() {
  // Empty Base64 variable – placeholder
  const htmlBase64 = "";

  if (!htmlBase64) {
    alert("The Base64 variable is still empty – waiting for content.");
    return;
  }

  const newTab = window.open('about:blank', '_blank');
  if (newTab) {
    const decodedHtml = decodeURIComponent(escape(atob(htmlBase64)));
    newTab.document.write(decodedHtml);
    newTab.document.close();
  } else {
    alert('Pop-up blocker is preventing the tab from opening.');
  }
}
